const suffix = Date.now();

pm.collectionVariables.set("updatedName", "Mahfuz Tinab " + suffix);
pm.collectionVariables.set("updatedEmail", "mahfuz." + suffix + "@example.com");
pm.collectionVariables.set("updatedCompany", "Ostad " + suffix);

const response = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Returned ID matches saved User ID", function () {
    pm.expect(response.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("Phone number is not empty", function () {
    pm.expect(response.phone).to.be.a("string").and.not.empty;
});

pm.test("Name is updated", function () {
    pm.expect(response.name).to.eql(
        pm.collectionVariables.get("updatedName")
    );
});

pm.test("Email is updated", function () {
    pm.expect(response.email).to.eql(
        pm.collectionVariables.get("updatedEmail")
    );
});

pm.test("Company name is updated", function () {
    pm.expect(response.company.name).to.eql(
        pm.collectionVariables.get("updatedCompany")
    );
});
